import{c as e,Q as r,j as i,m as s}from"./chunks/framework.BPmZ9ESu.js";const g=JSON.parse('{"title":"Grille d’évaluation — TP3","description":"Grille critériée — Rapport Word sur le milieu de l’informatique","frontmatter":{"title":"Grille d’évaluation — TP3","description":"Grille critériée — Rapport Word sur le milieu de l’informatique","aside":true},"headers":[],"relativePath":"grilles/grille-tp3-word-profession.md","filePath":"grilles/grille-tp3-word-profession.md"}'),n={name:"grilles/grille-tp3-word-profession.md"};function o(a,t,d,l,u,c){return r(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="grille-d-evaluation-—-tp3" tabindex="-1">Grille d’évaluation — TP3 <a class="header-anchor" href="#grille-d-evaluation-—-tp3" aria-label="Permalink to &quot;Grille d’évaluation — TP3&quot;">​</a></h1><p><strong>Rapport Word sur le milieu de l’informatique (Word)</strong></p><blockquote><p><strong>Échelle descriptive</strong><br><strong>Excellent = 100 %</strong> · <strong>Bien = 80 %</strong> · <strong>Correct = 60 %</strong> · <strong>Insuffisant = 40 %</strong> · <strong>Invalide = 0 %</strong></p></blockquote><hr><h2 id="partie-a-—-modele-word-40" tabindex="-1">Partie A — Modèle Word (40 %) <a class="header-anchor" href="#partie-a-—-modele-word-40" aria-label="Permalink to &quot;Partie A — Modèle Word (40 %)&quot;">​</a></h2><h3 id="_1-structure-du-modele-et-organisation-du-document-15" tabindex="-1">1) Structure du modèle et organisation du document (15 %) <a class="header-anchor" href="#_1-structure-du-modele-et-organisation-du-document-15" aria-label="Permalink to &quot;1) Structure du modèle et organisation du document (15 %)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Page de présentation complète et conforme</li><li>Page blanche réellement vide</li><li>Table des matières automatique sur sa propre page</li><li>Bibliographie fictive présente</li><li>Structure générale du modèle claire et réutilisable</li><li>Fichier de type .dotx</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Structure complète, conforme et directement réutilisable comme modèle.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Structure globalement correcte avec quelques détails mineurs à ajuster.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Structure partielle ou certains éléments mal intégrés.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Plusieurs éléments manquent ou sont mal organisés.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Modèle absent, très incomplet ou non conforme.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_2-mise-en-forme-styles-et-maitrise-des-outils-word-15" tabindex="-1">2) Mise en forme, styles et maîtrise des outils Word (15 %) <a class="header-anchor" href="#_2-mise-en-forme-styles-et-maitrise-des-outils-word-15" aria-label="Permalink to &quot;2) Mise en forme, styles et maîtrise des outils Word (15 %)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Titres de niveaux 1, 2 et 3 présents et cohérents</li><li>En-têtes et pieds de page conformes aux consignes</li><li>Pagination adéquate</li><li>Bordure de page présente au bon endroit</li><li>Mise en page soignée, cohérente et professionnelle</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Mise en forme maîtrisée, cohérente et professionnelle dans l’ensemble du modèle.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Mise en forme solide avec quelques écarts mineurs.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Mise en forme fonctionnelle, mais irrégulière ou partiellement conforme.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Mise en forme peu maîtrisée ou plusieurs erreurs visibles.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Mise en forme absente, incohérente ou non exploitable.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_3-elements-obligatoires-du-modele-10" tabindex="-1">3) Éléments obligatoires du modèle (10 %) <a class="header-anchor" href="#_3-elements-obligatoires-du-modele-10" aria-label="Permalink to &quot;3) Éléments obligatoires du modèle (10 %)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Au moins une citation avec référence dans la bibliographie</li><li>Au moins une note de bas de page</li><li>Tableau conforme au modèle, avec style personnalisé et légende</li><li>Au moins deux images</li><li>Légendes significatives avec lien cliquable vers la source</li><li>Positionnement des éléments conforme au modèle demandé</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Tous les éléments obligatoires sont présents, bien intégrés et conformes.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Éléments présents avec quelques imperfections mineures.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Éléments partiellement conformes ou incomplets.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Plusieurs éléments manquants ou mal réalisés.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Éléments obligatoires absents ou non fonctionnels.</td><td>0 %</td></tr></tbody></table><hr><h2 id="partie-b-—-rapport-sur-les-entreprises-60" tabindex="-1">Partie B — Rapport sur les entreprises (60 %) <a class="header-anchor" href="#partie-b-—-rapport-sur-les-entreprises-60" aria-label="Permalink to &quot;Partie B — Rapport sur les entreprises (60 %)&quot;">​</a></h2><h3 id="_4-introduction-tableau-des-entreprises-et-organisation-du-rapport-10" tabindex="-1">4) Introduction, tableau des entreprises et organisation du rapport (10 %) <a class="header-anchor" href="#_4-introduction-tableau-des-entreprises-et-organisation-du-rapport-10" aria-label="Permalink to &quot;4) Introduction, tableau des entreprises et organisation du rapport (10 %)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Introduction claire et structurée qui respecte la structure imposée</li><li>Tableau des entreprises complet et lisible</li><li>Liens cliquables présents lorsque demandés</li><li>Organisation logique des sections du rapport</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Introduction, tableau et organisation du rapport sont clairs, complets et bien structurés.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Ensemble cohérent avec de légers ajustements possibles.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Présence des éléments essentiels, mais structure ou clarté perfectible.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Organisation faible ou plusieurs éléments incomplets.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Introduction ou tableau absents, ou rapport mal structuré.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_5-presentation-des-entreprises-et-contenu-contextualise-25" tabindex="-1">5) Présentation des entreprises et contenu contextualisé (25 %) <a class="header-anchor" href="#_5-presentation-des-entreprises-et-contenu-contextualise-25" aria-label="Permalink to &quot;5) Présentation des entreprises et contenu contextualisé (25 %)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Trois entreprises présentées</li><li>Description, domaine d’activité, mission ou valeurs présents</li><li>Produits et/ou services informatiques décrits</li><li>Un poste différent est présenté pour chaque entreprise</li><li>Les tâches, responsabilités et compétences sont liées à l’entreprise analysée, et non décrites de façon générique</li><li>Logo et image ajoutés avec légendes</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Présentation complète, précise et bien adaptée à chaque entreprise.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Présentation pertinente avec quelques détails à approfondir.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Informations présentes mais parfois générales, inégales ou peu développées.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Présentation incomplète, peu contextualisée ou répétitive.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Présentation absente, très incomplète ou non conforme.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_6-analyse-comparative-et-comprehension-du-milieu-de-l-informatique-15" tabindex="-1">6) Analyse comparative et compréhension du milieu de l’informatique (15 %) <a class="header-anchor" href="#_6-analyse-comparative-et-comprehension-du-milieu-de-l-informatique-15" aria-label="Permalink to &quot;6) Analyse comparative et compréhension du milieu de l’informatique (15 %)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Comparaison pertinente entre les entreprises</li><li>Similarités et différences identifiées</li><li>Compréhension du milieu de travail en informatique perceptible</li><li>Conclusion cohérente avec le contenu du rapport</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Analyse claire, pertinente et démontrant une bonne compréhension du milieu.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Analyse juste et cohérente avec quelques nuances manquantes.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Analyse descriptive ou partiellement approfondie.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Analyse superficielle, incomplète ou peu pertinente.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Analyse absente ou ne répondant pas à la consigne.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_7-citations-bibliographie-et-qualite-des-sources-10" tabindex="-1">7) Citations, bibliographie et qualité des sources (10 %) <a class="header-anchor" href="#_7-citations-bibliographie-et-qualite-des-sources-10" aria-label="Permalink to &quot;7) Citations, bibliographie et qualité des sources (10 %)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Au moins deux citations intégrées au document</li><li>Bibliographie présente et conforme</li><li>Sources fiables et pertinentes</li><li>Sources liées au contenu présenté</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Citations et bibliographie complètes, pertinentes et bien intégrées.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Sources adéquates avec quelques détails de présentation à corriger.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Sources présentes mais limitées, incomplètes ou peu variées.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Peu de sources, citations faibles ou bibliographie incomplète.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Citations et bibliographie absentes ou non conformes.</td><td>0 %</td></tr></tbody></table><hr><h3 id="respect-des-consignes-et-modalites-de-remise-penalite" tabindex="-1">Respect des consignes et modalités de remise (pénalité) <a class="header-anchor" href="#respect-des-consignes-et-modalites-de-remise-penalite" aria-label="Permalink to &quot;Respect des consignes et modalités de remise (pénalité)&quot;">​</a></h3><p><strong>Vérifications</strong></p><ul><li>Fichiers remis dans les bons formats</li><li>Noms de fichiers exacts et conformes</li><li>Exportation PDF effectuée pour les documents Word demandés</li><li>Tous les fichiers demandés sont présents dans le ZIP</li></ul><table tabindex="0"><thead><tr><th>Situation observée</th><th>Pénalité appliquée</th></tr></thead><tbody><tr><td>Toutes les consignes sont respectées</td><td><strong>0 %</strong></td></tr><tr><td>Oublis mineurs ou incohérences</td><td><strong>−5 %</strong></td></tr><tr><td>Non-respect important des consignes</td><td><strong>−10 %</strong></td></tr></tbody></table><hr><h3 id="qualite-de-la-langue-penalite" tabindex="-1">Qualité de la langue (pénalité) <a class="header-anchor" href="#qualite-de-la-langue-penalite" aria-label="Permalink to &quot;Qualité de la langue (pénalité)&quot;">​</a></h3><p>Chaque faute de français entraîne une pénalité de <strong>−0,25 point</strong>, jusqu’à un maximum de <strong>−20 points</strong>.</p><table tabindex="0"><thead><tr><th>Situation observée</th><th>Pénalité appliquée</th></tr></thead><tbody><tr><td>Chaque faute relevée</td><td><strong>−0,25 point</strong></td></tr><tr><td>Maximum applicable</td><td><strong>−20 points</strong></td></tr></tbody></table><hr><h3 id="retard-dans-la-remise-penalite" tabindex="-1">Retard dans la remise (pénalité) <a class="header-anchor" href="#retard-dans-la-remise-penalite" aria-label="Permalink to &quot;Retard dans la remise (pénalité)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Retard observé</th><th>Pénalité appliquée</th></tr></thead><tbody><tr><td>≤ 24 h</td><td><strong>−10 %</strong></td></tr><tr><td>≤ 48 h</td><td><strong>−20 %</strong></td></tr><tr><td>≤ 72 h</td><td><strong>−30 %</strong></td></tr><tr><td>Plus de 72 h</td><td><strong>Travail refusé</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>La pénalité pour retard s’applique <strong>après</strong> l’évaluation des critères et <strong>s’additionne</strong>, s’il y a lieu, à la pénalité pour non-respect des consignes.</p></div>',53)])])}const m=e(n,[["render",o]]);export{g as __pageData,m as default};
